result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "agg_engine.py", "content": """"A minimal CSV query engine with SQL-style aggregation.

Supported queries (no WHERE clause):

    SELECT COUNT(*) FROM table
    SELECT COUNT(col), SUM(col), AVG(col), MIN(col), MAX(col) FROM table
    SELECT group_col, COUNT(*), COUNT(col), ... FROM table GROUP BY group_col

Semantics match SQLite:
  * Empty string cells in the CSV are treated as NULL.
  * COUNT(*) counts all rows; COUNT(col) counts only non-NULL values.
  * SUM/AVG/MIN/MAX ignore NULL values entirely.
  * Aggregates over zero non-NULL values yield NULL (None in Python),
    except COUNT which yields 0.
"""

from __future__ import annotations

import csv
import re
from typing import Any


class QueryError(ValueError):
    pass


AGG_FUNCS = ("COUNT", "SUM", "AVG", "MIN", "MAX")

_SELECT_RE = re.compile(
    r"^select\s+(?P<select>.+?)\s+from\s+(?P<table>\S+)"
    r"(?:\s+group\s+by\s+(?P<group>\S+))?\s*;?\s*$",
    re.IGNORECASE | re.DOTALL,
)
_ITEM_RE = re.compile(r"^(?P<func>[A-Za-z]+)\s*\(\s*(?P<arg>[^)]*)\s*\)$")


def _load_csv(path: str) -> tuple[list[str], list[dict[str, Any]]]:
    """Load a CSV file. Empty strings become None (NULL)."""
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            raise QueryError("CSV file has no header row")
        rows = []
        for raw in reader:
            if not raw:
                continue  # skip completely blank lines
            row = {}
            for i, col in enumerate(header):
                val: Any = raw[i] if i < len(raw) else ""
                row[col] = None if val == "" else val
            rows.append(row)
    return header, rows


def _parse_select_item(item: str) -> tuple[str, str | None]:
    """Parse one select item like 'COUNT(*)' or 'SUM(amount)'.

    Returns (FUNC, column-or-'*'--or-None-for-bare-column).
    """
    item = item.strip()
    m = _ITEM_RE.match(item)
    if not m:
        # bare column (only meaningful as a GROUP BY key)
        return ("COLUMN", item)
    func = m.group("func").upper()
    arg = m.group("arg").strip()
    if func not in AGG_FUNCS:
        raise QueryError(f"Unsupported aggregate function: {func}")
    if func != "COUNT" and arg == "*":
        raise QueryError(f"{func}(*) is not supported")
    if arg == "":
        raise QueryError(f"{func}() requires an argument")
    return (func, arg)


def _aggregate(func: str, values: list[Any]) -> Any:
    """Compute an aggregate over non-NULL values of one column."""
    non_null = [v for v in values if v is not None]
    if func == "COUNT":
        return len(non_null)
    if not non_null:
        return None  # SQL semantics: NULL when no rows contribute
    nums = [float(v) for v in non_null]
    if func == "SUM":
        total = sum(nums)
        return int(total) if total.is_integer() else total
    if func == "AVG":
        avg = sum(nums) / len(nums)
        return round(avg, 10)  # avoid float noise like 199.97499999999997
    if func == "MIN":
        return min(nums)
    if func == "MAX":
        return max(nums)
    raise QueryError(f"Unsupported aggregate function: {func}")


def execute(csv_path: str, sql: str) -> list[dict[str, Any]]:
    """Execute a supported aggregation query against a CSV file."""
    m = _SELECT_RE.match(sql.strip())
    if not m:
        raise QueryError(
            "Only SELECT <aggregates> FROM <table> [GROUP BY <col>] is supported"
        )
    select_items = [_parse_select_item(p) for p in m.group("select").split(",")]
    group_col = m.group("group")
    if group_col:
        group_col = group_col.strip()

    _, rows = _load_csv(csv_path)

    if group_col is None:
        result_row: dict[str, Any] = {}
        for func, col in select_items:
            if func == "COLUMN":
                raise QueryError("Bare columns require GROUP BY")
            key = f"{func}({col})"
            if col == "*":
                result_row[key] = sum(1 for _ in rows) if func == "COUNT" else None
            else:
                result_row[key] = _aggregate(func, [r.get(col) for r in rows])
        return [result_row]

    # GROUP BY path
    buckets: dict[Any, list[dict[str, Any]]] = {}
    for r in rows:
        key = r.get(group_col)
        buckets.setdefault(key, []).append(r)

    results = []
    for key in sorted(buckets, key=lambda k: (k is None, str(k))):
        bucket_rows = buckets[key]
        out: dict[str, Any] = {group_col: key}
        for func, col in select_items:
            if func == "COLUMN":
                if col != group_col:
                    raise QueryError(f"Column {col!r} must be the GROUP BY column")
                continue
            key_name = f"{func}({col})"
            if col == "*":
                out[key_name] = len(bucket_rows) if func == "COUNT" else None
            else:
                out[key_name] = _aggregate(func, [r.get(col) for r in bucket_rows])
        results.append(out)
    return results
