result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test_agg_engine.py", "content": """"Tests for agg_engine.py — every expected value is cross-checked
against sqlite3 loading the same CSV with empty strings converted to NULL."""

import csv
import sqlite3

import pytest

from agg_engine import execute

CSV_PATH = "sales.csv"
AMOUNT = "amount"
REGION = "region"


def load_sqlite() -> sqlite3.Connection:
    """Load the CSV into an in-memory SQLite DB, '' -> NULL."""
    conn = sqlite3.connect(":memory:")
    conn.execute("CREATE TABLE sales (order_id TEXT, region TEXT, amount REAL, product TEXT)")
    with open(CSV_PATH, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            amount = row[AMOUNT]
            conn.execute(
                "INSERT INTO sales VALUES (?, ?, ?, ?)",
                (
                    row["order_id"] or None,
                    row[REGION] or None,
                    float(amount) if amount != "" else None,
                    row["product"] or None,
                ),
            )
    return conn


@pytest.fixture(scope="module")
def db():
    conn = load_sqlite()
    yield conn
    conn.close()


def q(sql):
    return execute(CSV_PATH, sql)


def scalar(sqlite_conn, sql):
    return sqlite_conn.execute(sql).fetchone()[0]


# ---------------------------------------------------------------- global aggregates

def test_count_star_matches_sqlite(db):
    assert q("SELECT COUNT(*) FROM sales")[0]["COUNT(*)"] == scalar(db, "SELECT COUNT(*) FROM sales")


def test_count_col_matches_sqlite(db):
    assert q("SELECT COUNT(amount) FROM sales")[0]["COUNT(amount)"] == scalar(db, "SELECT COUNT(amount) FROM sales")


def test_count_star_differs_from_count_amount(db):
    """COUNT(*) must include rows whose amount is NULL; COUNT(amount) must not."""
    cstar = q("SELECT COUNT(*) FROM sales")[0]["COUNT(*)"]
    ccol = q("SELECT COUNT(amount) FROM sales")[0]["COUNT(amount)"]
    assert cstar == 25  # sanity: sample has 25 data rows
    assert ccol < cstar
    assert ccol == scalar(db, "SELECT COUNT(amount) FROM sales")


def test_sum_matches_sqlite(db):
    assert q("SELECT SUM(amount) FROM sales")[0]["SUM(amount)"] == pytest.approx(
        scalar(db, "SELECT SUM(amount) FROM sales")
    )


def test_avg_matches_sqlite(db):
    assert q("SELECT AVG(amount) FROM sales")[0]["AVG(amount)"] == pytest.approx(
        scalar(db, "SELECT AVG(amount) FROM sales")
    )


def test_min_matches_sqlite(db):
    assert q("SELECT MIN(amount) FROM sales")[0]["MIN(amount)"] == pytest.approx(
        scalar(db, "SELECT MIN(amount) FROM sales")
    )


def test_max_matches_sqlite(db):
    assert q("SELECT MAX(amount) FROM sales")[0]["MAX(amount)"] == pytest.approx(
        scalar(db, "SELECT MAX(amount) FROM sales")
    )


def test_multiple_aggregates_in_one_query_match_sqlite(db):
    row = q("SELECT COUNT(*), COUNT(amount), SUM(amount), AVG(amount), MIN(amount), MAX(amount) FROM sales")[0]
    assert row["COUNT(*)"] == scalar(db, "SELECT COUNT(*) FROM sales")
    assert row["COUNT(amount)"] == scalar(db, "SELECT COUNT(amount) FROM sales")
    assert row["SUM(amount)"] == pytest.approx(scalar(db, "SELECT SUM(amount) FROM sales"))
    assert row["AVG(amount)"] == pytest.approx(scalar(db, "SELECT AVG(amount) FROM sales"))
    assert row["MIN(amount)"] == pytest.approx(scalar(db, "SELECT MIN(amount) FROM sales"))
    assert row["MAX(amount)"] == pytest.approx(scalar(db, "SELECT MAX(amount) FROM sales"))


# ---------------------------------------------------------------- GROUP BY

def group_row(rows, key):
    for r in rows:
        if r[REGION] == key:
            return r
    raise AssertionError(f"group {key!r} not found in {rows}")


def test_group_by_regions_match_sqlite_count(db):
    got = sorted(q(f"SELECT {REGION}, COUNT(*) FROM sales GROUP BY {REGION}"), key=lambda r: str(r[REGION]))
    want = db.execute(
        f"SELECT {REGION}, COUNT(*) FROM sales GROUP BY {REGION} ORDER BY {REGION}"
    ).fetchall()
    assert [(r[REGION], r["COUNT(*)"]) for r in got] == [tuple(w) for w in want]


def test_group_by_sum_per_region_matches_sqlite(db):
    got = sorted(q(f"SELECT {REGION}, SUM({AMOUNT}) FROM sales GROUP BY {REGION}"), key=lambda r: str(r[REGION]))
    want = {
        region: s
        for region, s in db.execute(
            f"SELECT {REGION}, SUM({AMOUNT}) FROM sales GROUP BY {REGION}"
        )
    }
    for r in got:
        assert r[f"SUM({AMOUNT})"] == pytest.approx(want[r[REGION]])


def test_group_by_avg_min_max_match_sqlite(db):
    got = q(f"SELECT {REGION}, AVG({AMOUNT}), MIN({AMOUNT}), MAX({AMOUNT}) FROM sales GROUP BY {REGION}")
    want = {
        region: (a, mn, mx)
        for region, a, mn, mx in db.execute(
            f"SELECT {REGION}, AVG({AMOUNT}), MIN({AMOUNT}), MAX({AMOUNT}) FROM sales GROUP BY {REGION}"
        )
    }
    for r in got:
        a, mn, mx = want[r[REGION]]
        assert r[f"AVG({AMOUNT})"] == pytest.approx(a)
        assert r[f"MIN({AMOUNT})"] == pytest.approx(mn)
        assert r[f"MAX({AMOUNT})"] == pytest.approx(mx)


def test_all_null_group_returns_none_for_sum_matching_sqlite(db):
    """The 'Unknown' group has ONLY null amounts: SUM must be NULL/None,
    exactly like SQLite; COUNT(*) still counts its rows."""
    rows = q(f"SELECT {REGION}, COUNT(*), SUM({AMOUNT}) FROM sales GROUP BY {REGION}")
    unk = group_row(rows, "Unknown")

    # the sample really contains an all-NULL group
    nulls_only = [
        g for g, s in db.execute(
            f"SELECT {REGION}, SUM({AMOUNT}) FROM sales GROUP BY {REGION} WHERE SUM({AMOUNT}) IS NULL"
        )
    ]
    assert "Unknown" in nulls_only

    # engine agrees with SQLite: SUM over only-NULL group is None, COUNT(*) > 0
    assert unk[f"SUM({AMOUNT})"] is None
    sqlite_unknown_count = scalar(
        db, f"SELECT COUNT(*) FROM sales WHERE {REGION} = 'Unknown'"
    )
    assert unk["COUNT(*)"] == sqlite_unknown_count > 0


def test_all_null_group_count_of_amount_is_zero_and_avg_is_none(db):
    rows = q(f"SELECT {REGION}, COUNT({AMOUNT}), AVG({AMOUNT}) FROM sales GROUP BY {REGION}")
    unk = group_row(rows, "Unknown")
    assert unk[f"COUNT({AMOUNT})"] == 0
    assert unk[f"AVG({AMOUNT})"] is None


# ---------------------------------------------------------------- robustness

def test_avg_over_zero_non_null_values_is_none(tmp_path):
    p = tmp_path / "t.csv"
    p.write_text("k,v\na,\na,\n")
    rows = execute(str(p), "SELECT k, AVG(v) FROM t GROUP BY k")
    assert rows[0]["AVG(v)"] is None


def test_case_insensitive_keywords():
    assert q("select count(*) from sales")[0]["COUNT(*)"] == 25
